CREATE LOCAL TEMPORARY TABLE PALACE_IMPORT_CHARACTER (
    REF VARCHAR(12) PRIMARY KEY, NAME VARCHAR(255) NOT NULL, AFFILIATION VARCHAR(120) NOT NULL
);
