CREATE LOCAL TEMPORARY TABLE PALACE_IMPORT_RESOLVED (
    REF VARCHAR(12) PRIMARY KEY, CHARACTER_ID BIGINT NOT NULL UNIQUE
);
INSERT INTO PALACE_IMPORT_RESOLVED
SELECT candidate.REF, local_character.ID
FROM PALACE_IMPORT_CHARACTER candidate
JOIN ORIGINAL_CHARACTER local_character ON local_character.NAME=candidate.NAME
  AND local_character.WORLD='ALTER_PALACE'
  AND COALESCE(local_character.AFFILIATION, '')=candidate.AFFILIATION;
CREATE LOCAL TEMPORARY TABLE PALACE_IMPORT_VALIDATION (
    MATCHED INTEGER CHECK (MATCHED=25)
);
INSERT INTO PALACE_IMPORT_VALIDATION SELECT COUNT(*) FROM PALACE_IMPORT_RESOLVED;
CREATE LOCAL TEMPORARY TABLE PALACE_IMPORT_RELATION (
    SOURCE_REF VARCHAR(12) NOT NULL, TARGET_REF VARCHAR(12) NOT NULL,
    LABEL VARCHAR(60) NOT NULL, DETAIL VARCHAR(2000) NOT NULL,
    PRIMARY KEY (SOURCE_REF, TARGET_REF)
);
