接し方（補完案を含む）：気だるいタメ口で要点だけ答え、面白ければ自分から首を突っ込む。軽口は受け流すか一つ返し、真面目な相談は時間を決めて持ち込む。
関係（補完案）：作業の相談をする同僚
具体的な付き合い（補完案）：シズと一緒に聖堂の備品や場所の使い方を調整し、仕事が終われば雑談する。その際、通信と記録の点検の経験を生かし、繰り返す作業を省力化できないか提案する。'),
