CREATE LOCAL TEMPORARY TABLE PALACE_IMPORT_APPLY (
    SOURCE_ID BIGINT NOT NULL, TARGET_ID BIGINT NOT NULL,
    LABEL VARCHAR(60) NOT NULL, DETAIL VARCHAR(2000) NOT NULL, EXISTING_ID BIGINT,
    PRIMARY KEY (SOURCE_ID, TARGET_ID)
);
INSERT INTO PALACE_IMPORT_APPLY
SELECT source_character.CHARACTER_ID, target_character.CHARACTER_ID, candidate.LABEL, candidate.DETAIL,
       (SELECT MIN(existing.ID) FROM CHARACTER_RELATION existing
        WHERE existing.SOURCE_ID=source_character.CHARACTER_ID
          AND existing.TARGET_ID=target_character.CHARACTER_ID)
FROM PALACE_IMPORT_RELATION candidate
JOIN PALACE_IMPORT_RESOLVED source_character ON source_character.REF=candidate.SOURCE_REF
JOIN PALACE_IMPORT_RESOLVED target_character ON target_character.REF=candidate.TARGET_REF;

-- Reject descriptions that would exceed the application's storage before writing anything.
CREATE LOCAL TEMPORARY TABLE PALACE_IMPORT_LENGTH (
    DESCRIPTION_LENGTH INTEGER CHECK (DESCRIPTION_LENGTH<=2000)
);
INSERT INTO PALACE_IMPORT_LENGTH
SELECT CHAR_LENGTH(COALESCE(existing.DESCRIPTION, ''))+CHAR_LENGTH(candidate.DETAIL)+2
FROM PALACE_IMPORT_APPLY candidate
JOIN CHARACTER_RELATION existing ON existing.ID=candidate.EXISTING_ID
WHERE LOCATE('【パレス関係詳細】', COALESCE(existing.DESCRIPTION, ''))=0;

UPDATE CHARACTER_RELATION existing
SET DESCRIPTION = CASE WHEN COALESCE(existing.DESCRIPTION,'')='' THEN '' ELSE existing.DESCRIPTION || CHAR(10) || CHAR(10) END
    || (SELECT candidate.DETAIL FROM PALACE_IMPORT_APPLY candidate WHERE candidate.EXISTING_ID=existing.ID)
WHERE LOCATE('【パレス関係詳細】', COALESCE(existing.DESCRIPTION, ''))=0
  AND EXISTS (SELECT 1 FROM PALACE_IMPORT_APPLY candidate WHERE candidate.EXISTING_ID=existing.ID);
INSERT INTO CHARACTER_RELATION (SOURCE_ID, TARGET_ID, RELATION_TYPE, DESCRIPTION)
SELECT SOURCE_ID, TARGET_ID, LABEL, DETAIL
FROM PALACE_IMPORT_APPLY WHERE EXISTING_ID IS NULL;
COMMIT;
